            assert(blocks.dom() =~= old_blocks.dom().insert(block.key()));
            assert(blocks.dom().len() == len);

            assert((len - 1) * block_size + block_size == len * block_size) by(nonlinear_arith);
            crate::layout::get_block_start_defn(block.key());

            (ptraw2, blocks)
        }
    }
